    @SubscribeEvent public static void server(ServerTickEvent.Post event){if(!ACTIVE||REVIEW||finished)return;if(closing){settling.tick(event.getServer());if(settling.ready()||settling.failed()){if(settling.failed()){REPORT.addProperty("passed",false);REPORT.addProperty("reason",settling.failure());}REPORT.add("settled",settling.report());write();finished=true;Minecraft.getInstance().execute(()->{var game=Minecraft.getInstance();if(game.level!=null)game.level.disconnect();game.disconnect(new TitleScreen());});}return;}if(level!=null&&phase==1&&chunk<289){int x=chunk%17-8,z=chunk/17-8;level.getChunk(x,z);chunk++;}if(ship!=null&&!closing){try{var p=WaveShipFixture.position(ship);minY=Math.min(minY,p.y);maxY=Math.max(maxY,p.y);var q=WaveShipFixture.orientation(ship);maxTilt=Math.max(maxTilt,Math.acos(Math.clamp(q.transform(new org.joml.Vector3d(0,1,0)).y,-1,1)));}catch(Exception e){throw new IllegalStateException(e);}}}
